options.getOption:
// The countries with the most nuclear power in service at the end of the time brush's window, in GW:
// what was already in service when the window opened (orange, as on the map) and what entered
// service during it (pale yellow). Click a country to follow it everywhere; click it again to let go.
// Frame A: country, gw_before, gw_new.

// @constants begin
const VAR = 'country';
const BEFORE = '#FF9830';
const NEW = '#FFE7A3';
// @constants end

const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);

// The chart redraws when the picked country changes: ${country}.
const picked = context.grafana.replaceVariables('${' + VAR + '}');
const countries = col('country').map(String);
const before = col('gw_before').map(Number);
const added = col('gw_new').map(Number);
const faded = (i) => picked !== '' && countries[i] !== picked;

const chart = context.panel.chart;
chart.off('click');
chart.on('click', (event) => {
  const name = countries[event.dataIndex];
  context.grafana.locationService.partial({ ['var-' + VAR]: name === picked ? '' : name }, true);
});

const bar = (name, values, color) => ({
  name,
  type: 'bar',
  stack: 'gw',
  barMaxWidth: 16,
  itemStyle: { color },
  data: values.map((v, i) => ({ value: v, itemStyle: { color, opacity: faded(i) ? 0.3 : 1 } })),
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 24, top: 28, bottom: 8, containLabel: true },
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 14, itemHeight: 10 },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    valueFormatter: (v) => (Number(v) || 0).toLocaleString('en-US', { maximumFractionDigits: 1 }) + ' GW',
  },
  xAxis: {
    type: 'value',
    axisLabel: { color: muted, formatter: '{value} GW' },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  yAxis: {
    type: 'category',
    inverse: true,
    data: countries,
    axisLabel: {
      interval: 0,
      color: (value) => (picked !== '' && value !== picked ? muted : theme.colors.text.primary),
      formatter: (value) => (value === picked ? '{picked|' + value + '}' : value),
      rich: { picked: { fontWeight: 'bold', color: theme.colors.text.primary } },
    },
    axisTick: { show: false },
  },
  series: [bar('In service before the window', before, BEFORE), bar('Entered service in the window', added, NEW)],
};

