options.getOption:
// Nuclear electricity, year by year, 1965 to 2025: the countries that made the most, stacked, and the
// rest of the world (the World's total less theirs), in TWh; the share of the World's electricity
// from nuclear power as a dashed line on the right axis. The time brush's window is shaded, and the
// three accidents and Germany's last day are marked. A country picked in the ranking stands out, and
// the dashed line becomes its own share.
// Frame A: time, grp, twh, ord. Frame B: time, share.

// @constants begin
const COLORS = {
  'United States': '#5794F2',
  France: '#B877D9',
  China: '#F2CC0C',
  Japan: '#F2495C',
  Russia: '#73BF69',
  'South Korea': '#8AB8FF',
  Germany: '#4AC1C9',
  'Rest of the world': '#6E7079',
};
const PICKED_COLOR = '#FF9830';
const EVENTS = [
  ['1979-03-28', 'Three Mile Island'],
  ['1986-04-26', 'Chernobyl'],
  ['2011-03-11', 'Fukushima'],
  ['2023-04-15', "Germany's last three"],
];
// @constants end

const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const grid = theme.colors.border.weak;
const series = context.panel.data.series;
const frameA = series.find((f) => f.refId === 'A');
const frameB = series.find((f) => f.refId === 'B');
const col = (frame, name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);

const picked = context.grafana.replaceVariables('${country}');
const lo = Date.parse(context.grafana.replaceVariables('${t_lo}'));
const hi = Date.parse(context.grafana.replaceVariables('${t_hi}'));

const times = col(frameA, 'time').map(Number);
const groups = col(frameA, 'grp').map(String);
const twh = col(frameA, 'twh').map((v) => (v === null ? null : Number(v)));
const ords = col(frameA, 'ord').map(Number);
const order = [...new Map(groups.map((g, i) => [g, ords[i]])).entries()].sort((a, b) => a[1] - b[1]).map(([g]) => g);
const byGroup = new Map(order.map((g) => [g, []]));
groups.forEach((g, i) => byGroup.get(g).push([times[i], twh[i]]));

const colorOf = (g) => COLORS[g] ?? PICKED_COLOR;
const dim = (g) => picked !== '' && g !== picked && g !== 'Rest of the world';

const stacks = order.map((g, i) => ({
  name: g,
  type: 'line',
  stack: 'twh',
  symbol: 'none',
  lineStyle: { width: 0 },
  areaStyle: { opacity: dim(g) ? 0.25 : 0.85 },
  itemStyle: { color: colorOf(g) },
  emphasis: { focus: 'series' },
  data: byGroup.get(g),
  ...(i === 0
    ? {
        markArea:
          Number.isFinite(lo) && Number.isFinite(hi)
            ? { silent: true, itemStyle: { color: 'rgba(255, 152, 48, 0.14)' }, data: [[{ xAxis: lo }, { xAxis: hi }]] }
            : undefined,
        markLine: {
          silent: true,
          symbol: 'none',
          lineStyle: { color: muted, type: 'dotted', width: 1 },
          label: { color: muted, fontSize: 11, formatter: (p) => p.name, position: 'insideEndTop' },
          data: EVENTS.map(([day, name]) => ({ name, xAxis: Date.parse(day + 'T00:00:00Z') })),
        },
      }
    : {}),
}));

const shareTimes = col(frameB, 'time').map(Number);
const share = col(frameB, 'share').map((v) => (v === null ? null : Number(v)));
const shareLine = {
  name: 'Share of electricity from nuclear, ' + (picked === '' ? 'World' : picked) + ' (%)',
  type: 'line',
  yAxisIndex: 1,
  symbol: 'none',
  lineStyle: { width: 2, type: 'dashed', color: theme.colors.text.primary },
  itemStyle: { color: theme.colors.text.primary },
  data: shareTimes.map((t, i) => [t, share[i]]),
};

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 8, top: 40, bottom: 8, containLabel: true },
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 14, itemHeight: 10, type: 'scroll' },
  tooltip: {
    trigger: 'axis',
    valueFormatter: (v) => (v === null || v === undefined ? '–' : Math.round(v).toLocaleString('en-US')),
  },
  xAxis: {
    type: 'time',
    min: Date.UTC(1965, 0, 1),
    max: Date.UTC(2025, 11, 31),
    axisLabel: { color: muted },
    axisLine: { lineStyle: { color: grid } },
    splitLine: { show: false },
  },
  yAxis: [
    {
      type: 'value',
      name: 'TWh a year',
      nameTextStyle: { color: muted, align: 'left' },
      axisLabel: { color: muted },
      splitLine: { lineStyle: { color: grid } },
    },
    {
      type: 'value',
      name: '% of electricity',
      max: picked === '' ? 20 : 100,
      nameTextStyle: { color: muted, align: 'right' },
      axisLabel: { color: muted, formatter: '{value} %' },
      splitLine: { show: false },
    },
  ],
  series: [...stacks, shareLine],
};

